namespace {
class SAGenTestChecker
  : public Checker<
        check::Bind,
        check::BranchCondition
    > {
   mutable std::unique_ptr<BugType> BT;

   public:
      SAGenTestChecker()
          : BT(new BugType(this, "Unreliable overflow check after roundup_pow_of_two()",
